(()=>{
let identity=null,avatar=null,loading=false,busy=false,status='',name='',rerender=()=>{},generation=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photoUrl=()=>'/api/avatar?v='+encodeURIComponent(avatar?.updatedAt||'');
function paint(nextName=name){name=nextName;const photo=document.querySelector('#account-avatar'),fallback=document.querySelector('#account-avatar-fallback');if(!photo||!fallback)return;fallback.textContent=(name||identity||'B').trim().charAt(0).toUpperCase();fallback.hidden=!!avatar;photo.hidden=!avatar;if(avatar&&photo.getAttribute('src')!==photoUrl())photo.src=photoUrl();if(!avatar)photo.removeAttribute('src');photo.onerror=()=>{photo.hidden=true;fallback.hidden=false}}
function refresh(){paint();if(location.hash.startsWith('#account'))rerender()}
async function sync(account,onChange){rerender=onChange;const next=account?.ready&&account.signedIn?account.email:null;if(next===identity)return;const gen=++generation;identity=next;avatar=null;busy=false;loading=false;status='';paint();if(!next)return;loading=true;try{const r=await fetch('/api/avatar?meta=1',{credentials:'same-origin',cache:'no-store'}),data=await r.json();if(gen!==generation)return;if(!r.ok)throw Error(data.error||'Фото пока недоступно.');avatar=data.avatar}catch(e){if(gen===generation)status=e.message}finally{if(gen===generation){loading=false;refresh()}}}
function panel(){return `<section class="profile-photo" aria-label="Фотография профиля"><div>${avatar?`<img class="account-avatar profile-photo-preview" src="${esc(photoUrl())}" alt="Твоя фотография">`:`<span class="account-avatar profile-photo-preview" aria-hidden="true">${esc((name||identity||'B').charAt(0).toUpperCase())}</span>`}</div><div><h2>Твоя фотография</h2><label class="btn alt avatar-picker">${busy?'Сохраняю…':'Загрузить фото'}<input id="avatar-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Загрузить фотографию профиля" ${busy?'disabled':''}></label>${avatar?`<button type="button" class="avatar-remove" id="avatar-remove" ${busy?'disabled':''}>Удалить фото</button>`:''}<p>JPG, PNG или WebP · до 5 МБ.<br>Фото доступно только в твоём аккаунте.</p><p class="profile-photo-status" id="avatar-status" role="status" aria-live="polite">${esc(loading?'Загружаю профиль…':status)}</p></div></section>`}
async function encode(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Выбери JPG, PNG или WebP размером до 5 МБ.');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>16000000)throw Error('Фото слишком большое по разрешению. Выбери уменьшенную копию.');const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d'),size=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,512,512);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.82));if(!blob)throw Error('Не удалось обработать фото.');const bytes=new Uint8Array(await blob.arrayBuffer());let text='';for(let n=0;n<bytes.length;n+=32768)text+=String.fromCharCode(...bytes.subarray(n,n+32768));return btoa(text)}finally{bitmap.close()}}
async function change(method,file){if(busy)return;const gen=generation;busy=true;status='Сохраняю фотографию…';refresh();try{const body=method==='POST'?{image:await encode(file)}:{},r=await fetch('/api/avatar',{method,credentials:'same-origin',headers:await window.BoraAccount.apiHeaders(),body:JSON.stringify(body)}),data=await r.json();if(gen!==generation)return;if(!r.ok)throw Error(data.error||'Не удалось изменить фото.');avatar=data.avatar;status=avatar?'Фото сохранено.':'Фото удалено.'}catch(e){if(gen===generation)status=e.message}finally{if(gen===generation){busy=false;refresh()}}}
function bind(){const input=document.querySelector('#avatar-file'),remove=document.querySelector('#avatar-remove');if(input)input.onchange=()=>{const file=input.files?.[0];if(file)change('POST',file)};if(remove)remove.onclick=()=>change('DELETE')}
window.BoraProfile={sync,paint,panel,bind};
})();
